"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["38163"],{26970(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.fonte_nao_comporta_os_valores","status":422,"titulo":"A fonte nova n\xe3o comporta os valores do fato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.fonte_nao_comporta_os_valores","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) com uma origem das op\xe7\xf5es (`fonteValores`) que n\xe3o comporta os valores que o fato j\xe1 tem cadastrados no cat\xe1logo. Os valores cadastrados no pr\xf3prio cat\xe1logo s\xf3 existem na origem global; outra origem os deixaria sem uso, e a API n\xe3o os descarta em sil\xeancio. Desativar os valores n\xe3o resolve: o c\xf3digo de um valor nunca \xe9 removido do fato, e os valores desativados contam. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159.","A recusa vem na lista `errors` da resposta, com `field` igual a `fonteValores`. Nada \xe9 gravado."],"comoResolver":["Mantenha a origem global das op\xe7\xf5es e envie de novo a defini\xe7\xe3o com as demais altera\xe7\xf5es que voc\xea quer. Se as op\xe7\xf5es do fato precisam vir de outra origem, n\xe3o \xe9 poss\xedvel alterar este fato: cadastre um novo fato com a origem desejada e deixe de usar o atual (desative-o, se nada mais o citar).","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);